_W6 = [("Katamtaman hanggang sa malakas na hangin mula sa timog-kanluran hanggang kanluran ang iiral sa Gitna at Katimugang Luzon.", "Moderate to strong winds from the southwest to west will prevail over Central and Southern Luzon."), ("Mula naman sa hilagang-silangan hanggang hilagang-kanluran sa natitirang bahagi ng Luzon, ang baybaying dagat sa mga lugar na ito ay magiging katamtaman hanggang sa maalon.", "From the northeast to northwest in the rest of Luzon, the coastal waters of these areas will be moderate to rough."), ("Sa ibang dako, ang hangin ay magiging mahina hanggang sa katamtaman mula sa timog-kanluran na may banayad hanggang sa katamtamang pag-alon ng karagatan.", "Elsewhere, the winds will be light to moderate from the southwest with slight to moderate seas."), ("Ang araw ay sisikat alas-singko kuwarenta y singko ng umaga at lulubog alas-singko singkuwenta y kuwatro ng gabi.", "The sun will rise at a quarter to six in the morning and set at six minutes to six in the evening (the book’s key says sunrise 5:45 a.m. and sunset 5:54 p.m.).")]
