_M7 = [("Magiging maaliwalas ang panahon sa malawakang bahagi ng Pilipinas ngayong araw. Walang aasahang mga pag-ulan dahil sa walang kaulapan na makikita sa Timog Luzon, Visayas at Mindanao.", "The weather will be clear over a wide part of the Philippines today. No rains are expected because no cloud cover is seen in Southern Luzon, the Visayas and Mindanao."), ("Mananatiling makulimlim at makakaranas ng walang tigil na pag-ulan ang mga taga-Visayas at Mindanao na may kasamang pagkulog-pagkidlat.", "Visayas and Mindanao residents will continue to see overcast skies and nonstop rain with thunder and lightning."), ("Matinding init ng panahon ang mararanasan sa Metro Davao. Maaraw na may bahagyang ulap ang kalangitan. Iiral ang ganitong panahon buong araw at tinatayang magiging pinakamaalinsangan sa Metro Davao.", "Extreme heat will be experienced in Metro Davao. The sky is sunny with slight clouds. This weather will prevail all day and Metro Davao is estimated to be the most muggy.")]
_S8 = [("Ang mga isla ng Batanes at Calayan ay makakaranas ng maulap na kalangitan na may mahinang pag-ulan.", "The islands of Batanes and Calayan will experience cloudy skies with light rain."), ("Ang Mindanao ay magkakaroon ng maulap na papawirin na may mahina hanggang katamtamang pag-ulan at pagkidlat-pagkulog.", "Mindanao will have cloudy skies with light to moderate rain and thunderstorms."), ("Ang natitirang bahagi ng bansa ay magiging bahagyang maulap na may pulu-pulong pag-ulan o pagkidlat-pagkulog lalo na sa Kabikulan at Silangang Kabisayaan.", "The rest of the country will be partly cloudy with isolated rain showers or thunderstorms, especially in Bicol and Eastern Visayas."), ("Katamtaman hanggang sa malakas na hangin mula sa hilagang-silangan ang iiral sa Luzon, Silangang Kabisayaan at Silangang Mindanao at ang mga baybaying-dagat sa mga lugar na ito ay magiging katamtaman hanggang sa maalon.", "Moderate to strong winds from the northeast will prevail in Luzon, Eastern Visayas and Eastern Mindanao and the coastal waters of these areas will be moderate to rough."), ("Sa ibang dako, ang hangin ay mahina hanggang sa katamtaman mula sa hilagang-silangan na may banayad hanggang sa katamtaman ang pag-alon ng karagatan.", "Elsewhere, winds will be light to moderate from the northeast with slight to moderate seas.")]
_S9 = [("Nakakaapekto pa rin sa Mindanao ang namumuong sama ng panahon.", "The developing low-pressure area is still affecting Mindanao."), ("Samantala, ang Metro Manila at iba pang bahagi ng bansa ay makakaranas ng maaliwalas na panahon ngayong araw na ito bagamat may mga pagbuhos ng ulan sa dakong hapon o gabi.", "Meanwhile, Metro Manila and other parts of the country will experience clear weather today although there will be downpours in the afternoon or evening."), ("Pinakamalamig pa rin sa Baguio City sa kinse degrees Celsius at pinakamaalinsangan naman ang panahon sa Metro Manila, Tuguegarao City, Metro Davao at Zamboanga City sa trenta y tres degrees Celsius.", "It is still coldest in Baguio City at fifteen degrees Celsius and the weather is muggiest in Metro Manila, Tuguegarao City, Metro Davao and Zamboanga City at thirty-three degrees Celsius."), ("Ang araw ay sumikat kaninang alas-singko singkuwenta y kuwatro ng umaga at inaasahang lulubog mamayang alas-singko beynte singko ng hapon.", "The sun rose earlier at 5:54 in the morning and is expected to set later at 5:25 in the afternoon (as the book prints it).")]
