        + [M("Which conversation is about a hot, muggy day?", "A: bagong ligo lang ako, basa na ako sa pawis", ["B: sa Tagaytay", "C: bumabagyo na", "none"], "A."), M("Which conversation is about a trip to Tagaytay?", "B", ["A", "C", "none"], "B."), M("Which conversation is about a storm?", "C", ["A", "B", "none"], "C."), M("What does the mother give her son in conversation C?", "an umbrella", ["a coat only", "boots only", "money"], "payong."), M("What will they do on Lake Taal?", "ride a boat", ["swim", "fish", "camp"], "bangka."), M("Where do the children ride small horses?", "Paradizoo", ["Taal Volcano", "Lake Taal", "the mall"], "Paradizoo."), M("What is the weather in Batanes and Calayan?", "cloudy skies with light rain", ["clear skies", "heavy rain", "thunderstorms"], "Batanes."), M("What is the weather in Mindanao in Activity 8?", "cloudy with light to moderate rain and thunderstorms", ["clear and dry", "a typhoon", "snow"], "Mindanao."), M("What areas have moderate to strong winds in Activity 8?", "Luzon, Eastern Visayas and Eastern Mindanao", ["Palawan only", "Metro Manila only", "Cebu only"], "hangin."), M("Where is it coldest in Activity 9?", "Baguio City", ["Metro Manila", "Davao", "Zamboanga"], "Baguio."), M("What is the temperature in Baguio in Activity 9?", "fifteen degrees Celsius", ["thirty-three", "twenty-five", "ten"], "kinse."), M("What is affecting Mindanao in Activity 9?", "a developing low-pressure area", ["a typhoon", "a heat wave", "the habagat"], "sama ng panahon."), M("Which four places are the muggiest in Activity 9?", "Metro Manila, Tuguegarao, Metro Davao and Zamboanga", ["Baguio, Cebu, Davao and Manila", "Baguio only", "Palawan and Cebu"], "pinakamaalinsangan.")]
