_ZD = [("Zenaida", "Daisy, pasensiya na, hindi ako makakadalo sa binyag at sa hapunan dahil baha sa barangay namin dahil sa malakas na ulan.", "Daisy, I’m sorry, I can’t attend the baptism and the dinner because our barangay is flooded due to the heavy rain."), ("Daisy", "Walang problema, naiintindihan ko ang sitwasyon.", "No problem, I understand the situation."), ("Zenaida", "Tinawagan ko ang nanay ko na malapit sa bahay mo at nangako siyang dadalo sa binyag para sa akin.", "I called my mother, who lives near your house, and she promised to attend the baptism for me."), ("Daisy", "Salamat.", "Thank you."), ("Zenaida", "May regalo ako para sa anak mong babae at ibibigay ko sa susunod na linggo.", "I have a gift for your daughter and I will give it next week."), ("Daisy", "Walang anuman. Salamat sa tawag.", "You’re welcome. Thank you for calling.")]
_HF = [("Estudyante", "Magandang umaga po. Halos hindi po ako nakatulog kagabi dahil malakas ang ulan at napakalakas ng kulog at kidlat. Takot po ako sa kulog at kidlat.", "Good morning. I could hardly sleep last night because the rain was heavy and the thunder and lightning were very loud. I am scared of thunder and lightning."), ("Host family", "Magandang umaga rin. Ang Hunyo ang simula ng tag-ulan at mga bagyo. Normal lang ang kulog at kidlat dito sa Pilipinas.", "Good morning too. June is the start of the rainy season and typhoons. Thunder and lightning are quite normal here in the Philippines."), ("Estudyante", "Balak po naming magkaklase mag-swimming sa Subic bukas ng Sabado. Magandang oras po ba ito para bumiyahe?", "My classmates and I plan to go swimming in Subic tomorrow, Saturday. Is it a good time to travel?"), ("Host family", "Apat na oras lang ang Subic mula rito. Pero kapag malakas ang ulan, baka bumaha ang mga kalsada sa Maynila at madulas sa North Expressway. Ikansela na lang ninyo ang biyahe at hintayin ang susunod na ulat ng panahon.", "Subic is just four hours from here. But if it rains heavily, the roads in Manila might flood and the North Expressway might be slippery. Just cancel the trip and wait for the next weather update."), ("Estudyante", "Sige po. Tatawagan ko ang mga kaklase ko para ikansela ang biyahe.", "Okay. I will call my classmates to cancel the trip.")]
_FCN = [("Ang Silangang Kabisayaan at rehiyon ng CARAGA ay makakaranas ng maulap na kalangitan na may mahina hanggang sa katamtaman na pag-ulan o pagkidlat-pagkulog.", "Eastern Visayas and the CARAGA Region will experience cloudy skies with light to moderate rain or thunderstorms."), ("Ang Cagayan Valley at ang mga lalawigan ng Aurora at Quezon ay magiging maulap na may mahinang pag-ulan.", "Cagayan Valley and the provinces of Aurora and Quezon will be cloudy with light rain."), ("Ang Metro Manila at ang nalalabing bahagi ng bansa ay magkakaroon ng bahagyang maulap na papawirin.", "Metro Manila and the remaining parts of the country will have slightly cloudy skies."), ("Katamtaman hanggang sa malakas na hangin mula sa silangan hanggang sa timog-silangan ang iiral sa Hilagang Luzon at mula naman sa hilagang-silangan sa natitirang bahagi ng bansa.", "Moderate to strong winds from the east to southeast will prevail over Northern Luzon and from the northeast over the rest of the country."), ("Ang mga baybaying-dagat sa buong kapuluan ay magiging katamtaman hanggang sa maalon.", "The coastal waters throughout the archipelago will be moderate to rough.")]
_GL = [("bahagyang maulap", "slightly cloudy"), ("banayad", "slight"), ("basura", "garbage"), ("baybaying-dagat", "coast, seashore"), ("bilis", "speed"), ("bumabaha", "gets easily flooded"), ("buong bansa", "whole country"), ("dumadami", "is increasing"), ("Gitna", "Central"), ("katamtaman hanggang sa malakas", "moderate to strong"), ("kulog at kidlat", "thunder and lightning"), ("kumidlat", "there was lightning"), ("kumulog", "thundered"), ("lumipad", "flew"), ("lumolobo", "ballooning or increasing"), ("maalon", "rough (waves)"), ("madulas", "slippery"), ("mahina hanggang sa katamtaman", "light to moderate"), ("mahirap", "difficult"), ("matatakutin", "easily scared"), ("pag-alon ng karagatan", "movement of waves in the open seas or ocean"), ("pagtaya ng panahon", "weather forecast"), ("populasyon", "population"), ("pulu-pulong pag-ulan", "isolated rain showers"), ("sa ibang dako", "elsewhere"), ("takot", "afraid"), ("umaabuso", "are abusing"), ("umambon", "to rain lightly, to shower"), ("umiinit", "getting hotter"), ("umulan", "rained")]
_UVS = [("Bumabaha sa mabababang lugar sa lungsod tuwing tag-ulan.", "It floods in the low-lying areas of the city every rainy season."), ("Noong makalawa, kumidlat at kumulog nang maraming beses sa loob ng kalahating oras, dahil sa matinding bagyo.", "The day before yesterday, it flashed lightning and thundered many times within half an hour because of the severe storm."), ("Nagtago sa ilalim ng hagdan ang aso noong biglang kumulog.", "The dog hid under the stairs when it suddenly thundered."), ("Kahit umambon lang, magpayong ka. Mahirap ang magkasakit.", "Even if it only drizzles, use an umbrella. Getting sick is hard."), ("Malapit na siguro ang tag-araw. Umiinit na nitong mga nakaraang ilang araw.", "Summer must be near. It has been getting hotter these past few days."), ("Makulimlim at umulan kanina. Ngayon naman, maaraw.", "It was overcast and it rained earlier. Now it is sunny."), ("Karaniwan, kapag humina ang bagyo sa isang lugar, dumadaan daw ang mata ng bagyo.", "Usually, when the storm weakens in one place, they say the eye of the storm is passing."), ("Malakas na hangin at manaka-nakang pag-ulan ang umiral buong araw.", "Strong winds and occasional rain prevailed all day."), ("Kapag dumulas ang kalsada, dulot ng ulan, mag-ingat sa pagmamaneho.", "When the road becomes slippery because of the rain, be careful when driving."), ("Kapag umaraw, lumabas tayo at mamili sa Nepa Q-Mart.", "When it becomes sunny, let’s go out and shop at Nepa Q-Mart."), ("Bumagyo nang ilang araw sa probinsiya, kaya ngayon lang ako nakabalik.", "It stormed for several days in the province, so I only got back now."), ("Sana naman humangin nang konti. Sobrang init ng panahon, e.", "I hope the wind blows a little. The weather is so hot."), ("Sana naman tumila na ang ulan. Kung hindi, babaha dito.", "I hope the rain stops. If not, it will flood here."), ("Halos nasa pintuan na ako nang pumatak ang malakas na ulan.", "I was almost at the door when the heavy rain poured.")]
_FP = [("Ang nalalabing bahagi ng bansa ay magiging bahagyang maulap hanggang sa maulap na may pulu-pulong pag-ulan o pagkidlat-pagkulog.", "The remaining parts of the country will be slightly cloudy to cloudy with isolated rain showers or thunderstorms."), ("Maaaring makaranas ang ibang parte ng bansa ng maulap na panahon at pag-ulan na may kasamang kulog at kidlat mula Miyerkules.", "Other parts of the country may experience cloudy weather and rain with thunder and lightning starting Wednesday."), ("Magiging katamtaman hanggang sa maalon ang mga baybaying dagat sa mga lugar na ito.", "The coastal waters in these areas will be moderate to rough."), ("Sumemplang ang ilang motorcycle riders dahil sa basa at madulas na kalsada.", "Some motorcycle riders skidded because of the wet and slippery road."), ("Sa pagtaya ng panahon, maaasahan nga ba ang PAGASA?", "In weather forecasting, can PAGASA really be relied on?"), ("Makakaranas pa rin ang buong bansa ng mainit at maaliwalas na panahon ngayong umaga, at mga pulo-pulong pag-ulan sa dakong hapon o gabi.", "The whole country will still experience hot and clear weather this morning, and isolated rain showers in the afternoon or evening."), ("Sa ibang dako, magiging mahina ang hangin mula sa hilagang-silangan.", "Elsewhere, the wind from the northeast will be light.")]
